mkdir -p /tmp/sim && cat > /tmp/sim/s.py <<'E'
import sys
P=[l.split(';')[0].split() for l in open(sys.argv[1]+'/prog.pw9')]
P=[p for p in P if p]
r=dict(a=0,b=0,c=0,d=0)
v=lambda x:r[x] if x in r else int(x)
i=0;n=0;s=0
while 0<=i<len(P):
    p=P[i];o=p[0];n+=1;nx=i+1
    if o=='set':r[p[1]]=v(p[2])%65536
    elif o=='add':r[p[1]]=(r[p[1]]+v(p[2]))%65536
    elif o=='mul':r[p[1]]=(r[p[1]]*v(p[2]))%65536
    elif o=='mod':
        if v(p[2])>0:r[p[1]]%=v(p[2])
    elif o=='dec':r[p[1]]=max(0,r[p[1]]-1)
    elif o=='jnz':
        if v(p[1])!=0:nx=i+v(p[2])
    elif o=='skp':
        if v(p[1])<v(p[2]):nx=i+2
    elif o=='out':s+=v(p[1])
    i=nx
print(s,n)
E
cd /tmp/<path> && python3 -I /tmp/sim/s.py . | tee answer.txt
